<?php
session_start();
header('Cache-Control: no-store');
$role=$_SESSION['role']??'';
if(empty($_SESSION['user_id'])){header('Location: login.php');exit;}
if($role!=='admin'){http_response_code(403);header('Cache-Control: no-store');exit('Recovered Years is available to Admin only.');}
$embedded = ($_GET['embedded'] ?? '') === '1';
if (!$embedded) {
    $query = ['view' => 'recovered-years'];
    if (preg_match('/^\d{4}-\d{4}$/', $_GET['year'] ?? '')) $query['year'] = $_GET['year'];
    header('Location: index.php?' . http_build_query($query));
    exit;
}
if(empty($_SESSION['app_csrf']))$_SESSION['app_csrf']=bin2hex(random_bytes(32));
$back='archives';
?>
